name = #{name}, type = #{type}, discount_amount = #{discountAmount}, discount_rate = #{discountRate}, min_amount = #{minAmount}, max_discount = #{maxDiscount}, total_count = #{totalCount}, used_count = #{usedCount}, valid_days = #{validDays}, start_time = #{startTime}, end_time = #{endTime}, status = #{status}, description = #{description},
